import { describe, expect, it } from 'vitest';

import { AccountInformation } from '../../src/format/account';
import { DatabaseOptions } from '../../src/format/options';
import { PasswordDatabase } from '../../src/format/passwordDatabase';
import { accountsEqual, merge, REMOTE_SUFFIX } from '../../src/merge/merger';

/** A file-less database holding the given accounts (dummy password/salt). */
function db(
  accounts: AccountInformation[],
  revision = 0,
  options?: DatabaseOptions,
): PasswordDatabase {
  const database = new PasswordDatabase(
    { password: 'pw', salt: new Uint8Array(8) },
    options ?? new DatabaseOptions(),
  );
  database.setRevision(revision);
  for (const account of accounts) {
    database.addAccount(account);
  }
  return database;
}

/** A named account with overridable fields. */
function acc(name: string, fields: Partial<AccountInformation> = {}): AccountInformation {
  return new AccountInformation(
    name,
    fields.userId ?? 'user',
    fields.password ?? 'pass',
    fields.url ?? '',
    fields.notes ?? '',
  );
}

/** Account names in the database, sorted. */
function namesOf(database: PasswordDatabase): string[] {
  return database
    .getAccounts()
    .map((account) => account.accountName)
    .sort();
}

describe('added on one side', () => {
  it('keeps an account added only locally', () => {
    const result = merge(db([]), db([acc('x', { password: 'L' })]), db([]));
    expect(namesOf(result.merged)).toEqual(['x']);
    expect(result.merged.getAccount('x')?.password).toBe('L');
    expect(result.uploadRequired).toBe(true);
    expect(result.conflictCount).toBe(0);
  });

  it('keeps an account added only remotely', () => {
    const result = merge(db([]), db([]), db([acc('x', { password: 'R' })]));
    expect(namesOf(result.merged)).toEqual(['x']);
    expect(result.merged.getAccount('x')?.password).toBe('R');
    expect(result.uploadRequired).toBe(false); // remote already holds it
  });

  it('keeps an account added identically on both sides', () => {
    const result = merge(db([]), db([acc('x')]), db([acc('x')]));
    expect(namesOf(result.merged)).toEqual(['x']);
    expect(result.conflictCount).toBe(0);
    expect(result.uploadRequired).toBe(false);
  });

  it('conflicts when both sides added the same name differently', () => {
    const result = merge(
      db([]),
      db([acc('x', { password: 'L' })]),
      db([acc('x', { password: 'R' })]),
    );
    expect(namesOf(result.merged)).toEqual(['x', `x${REMOTE_SUFFIX}`]);
    expect(result.merged.getAccount('x')?.password).toBe('L');
    expect(result.merged.getAccount(`x${REMOTE_SUFFIX}`)?.password).toBe('R');
    expect(result.conflictCount).toBe(1);
    expect(result.uploadRequired).toBe(true);
  });
});

describe('present in all three', () => {
  it('keeps an unchanged account', () => {
    const result = merge(db([acc('x')]), db([acc('x')]), db([acc('x')]));
    expect(namesOf(result.merged)).toEqual(['x']);
    expect(result.conflictCount).toBe(0);
    expect(result.uploadRequired).toBe(false);
  });

  it('takes the remote edit when only the remote changed', () => {
    const result = merge(
      db([acc('x', { password: 'B' })]),
      db([acc('x', { password: 'B' })]),
      db([acc('x', { password: 'R' })]),
    );
    expect(result.merged.getAccount('x')?.password).toBe('R');
    expect(result.uploadRequired).toBe(false);
  });

  it('takes the local edit when only the local changed', () => {
    const result = merge(
      db([acc('x', { password: 'B' })]),
      db([acc('x', { password: 'L' })]),
      db([acc('x', { password: 'B' })]),
    );
    expect(result.merged.getAccount('x')?.password).toBe('L');
    expect(result.uploadRequired).toBe(true);
  });

  it('conflicts when both sides edited the same account', () => {
    const result = merge(
      db([acc('x', { password: 'B' })]),
      db([acc('x', { password: 'L' })]),
      db([acc('x', { password: 'R' })]),
    );
    expect(namesOf(result.merged)).toEqual(['x', `x${REMOTE_SUFFIX}`]);
    expect(result.merged.getAccount('x')?.password).toBe('L');
    expect(result.merged.getAccount(`x${REMOTE_SUFFIX}`)?.password).toBe('R');
    expect(result.conflictCount).toBe(1);
    expect(result.uploadRequired).toBe(true);
  });
});

describe('deletions', () => {
  it('deletes when the remote deleted an untouched account', () => {
    const result = merge(db([acc('x')]), db([acc('x')]), db([]));
    expect(namesOf(result.merged)).toEqual([]);
    expect(result.uploadRequired).toBe(false); // remote already lacks it
  });

  it('deletes when the local deleted an untouched account', () => {
    const result = merge(db([acc('x')]), db([]), db([acc('x')]));
    expect(namesOf(result.merged)).toEqual([]);
    expect(result.uploadRequired).toBe(true); // deletion must propagate
  });

  it('keeps the local edit when the remote deleted it (delete vs edit)', () => {
    const result = merge(
      db([acc('x', { password: 'B' })]),
      db([acc('x', { password: 'L' })]),
      db([]),
    );
    expect(namesOf(result.merged)).toEqual(['x']);
    expect(result.merged.getAccount('x')?.password).toBe('L');
    expect(result.conflictCount).toBe(0);
  });

  it('keeps the remote edit when the local deleted it (delete vs edit)', () => {
    const result = merge(
      db([acc('x', { password: 'B' })]),
      db([]),
      db([acc('x', { password: 'R' })]),
    );
    expect(namesOf(result.merged)).toEqual(['x']);
    expect(result.merged.getAccount('x')?.password).toBe('R');
  });

  it('drops an account deleted on both sides', () => {
    const result = merge(db([acc('x')]), db([]), db([]));
    expect(namesOf(result.merged)).toEqual([]);
    expect(result.uploadRequired).toBe(false);
  });
});

describe('conflict copy naming', () => {
  it('numbers the copy when "(remote)" is already taken', () => {
    const base = db([acc('x', { password: 'B' })]);
    const local = db([acc('x', { password: 'L' })]);
    const remote = db([
      acc('x', { password: 'R' }),
      acc(`x${REMOTE_SUFFIX}`, { password: 'old' }),
    ]);
    const result = merge(base, local, remote);
    expect(new Set(namesOf(result.merged))).toEqual(
      new Set(['x', 'x (remote)', 'x (remote 2)']),
    );
    expect(result.merged.getAccount('x (remote 2)')?.password).toBe('R');
    expect(result.conflictCount).toBe(1);
  });
});

describe('options and revision', () => {
  it('always takes DatabaseOptions from the local database', () => {
    const result = merge(
      db([]),
      db([acc('x')], 0, new DatabaseOptions('local-url', 'local-auth')),
      db([acc('y')], 0, new DatabaseOptions('remote-url', 'remote-auth')),
    );
    expect(result.merged.getDbOptions().remoteLocation).toBe('local-url');
    expect(result.merged.getDbOptions().authDBEntry).toBe('local-auth');
  });

  it('sets the merged revision to max(local, remote) + 1', () => {
    const result = merge(db([], 5), db([], 3), db([], 7));
    expect(result.merged.getRevision()).toBe(8);
  });

  it('reports the merged account count', () => {
    const result = merge(db([]), db([acc('a'), acc('b')]), db([acc('c')]));
    expect(result.accountCount).toBe(3);
  });
});

describe('base = null', () => {
  it('treats a missing base as empty (union of local and remote)', () => {
    const result = merge(
      null,
      db([acc('a', { password: 'L' })]),
      db([acc('b', { password: 'R' })]),
    );
    expect(namesOf(result.merged)).toEqual(['a', 'b']);
    expect(result.conflictCount).toBe(0);
  });
});

describe('accountsEqual', () => {
  it('is true for the same accounts (ignoring options)', () => {
    expect(accountsEqual(db([acc('x')]), db([acc('x')]))).toBe(true);
    expect(
      accountsEqual(
        db([acc('x')], 0, new DatabaseOptions('a')),
        db([acc('x')], 9, new DatabaseOptions('b')),
      ),
    ).toBe(true);
  });

  it('is false when a field differs or an account is missing', () => {
    expect(accountsEqual(db([acc('x')]), db([acc('x', { password: 'z' })]))).toBe(false);
    expect(accountsEqual(db([acc('x')]), db([]))).toBe(false);
  });
});
